// ⓪ ENTRADA DEL SUB-FLUJO · cadena · estrategia · CC#1 · 2026-10-09 · diseño v2 §3.7
// Este flujo PAGA un agente. El pedido trae `seco` EXPLÍCITO (true|false): no se asume nunca (lección 28-sep: un `dry_run` que moría en el primer nodo cobró US$ 0,37) · se DETIENE antes de gastar.
const e = $input.first().json || {}
if (typeof e.campana_id !== 'string' || e.campana_id.trim() === '') throw new Error('CADENA_SIN_CAMPANA · falta campana_id · se DETIENE y no escribe nada')
if (typeof e.seco !== 'boolean') throw new Error('CADENA_SECO_AUSENTE · el pedido debe traer seco explícito (true o false) · se DETIENE antes de gastar')
const tanda = false ? (Number.isInteger(e.tanda) && e.tanda >= 1 ? e.tanda : 1) : null
// el simulacro (respuestas enlatadas del agente, UNA por vuelta) SOLO existe en seco: en real se ignora por completo y el agente se llama de verdad
const simulacro = e.seco === true && Array.isArray(e.simulacro) ? e.simulacro : null
return [{ json: { paso: 'estrategia', campana_id: e.campana_id, seco: e.seco, tanda, simulacro, vuelta: 0, correccion: null, workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) } }]

// ① ARMAR EL PEDIDO A LA CADENA · la entrada de cada vuelta (la primera, o la que sigue a una corrección / un reintento)
const s = $input.first().json
const pedido = { accion: 'preparar', campana_id: s.campana_id, seco: s.seco, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
if (s.tanda !== null && s.tanda !== undefined) pedido.tanda = s.tanda
if (s.correccion) pedido.correccion = s.correccion
return [{ json: { ...s, pedido } }]

// ① ¿QUÉ DIJO `preparar`? · tres cosas buenas (lista para llamar · ya hecha · la campaña ya quedó en necesita_humano) y todo lo demás FALLA RUIDOSO antes de gastar
const s = $('① Armar el pedido').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
const base = { ...s }
delete base.pedido
if (status === 200 && b.ya_hecha === true) return [{ json: { ...base, fin: true, resultado: 'ya_hecha', detalle: b } }]
if (status === 200 && b.run_sdk) return [{ json: { ...base, fin: false, corrida_id: b.corrida_id, headers: b.headers || {}, run_sdk: b.run_sdk, intento: b.intento || 1 } }]
// el tope (de presupuesto o de intentos) ya dejó la campaña en necesita_humano con su reloj: no es un error del flujo, es un fin declarado
if (status === 409 && (b.error === 'presupuesto_agotado' || b.error === 'intentos_agotados')) return [{ json: { ...base, fin: true, resultado: 'necesita_humano', alerta: b.alerta || null, detalle: b } }]
throw new Error('CADENA_PREPARAR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · no se llamó a ningún agente')

// ② SIMULACRO · SOLO en seco: la respuesta enlatada del agente para esta vuelta (cero llamadas al modelo, US$ 0). En real este nodo NO existe en el camino.
// Cada elemento del simulacro es el objeto estructurado que el agente devolvería, o `{ "__fallo": "texto" }` para simular una llamada que falla.
const s = $input.first().json
const lista = Array.isArray(s.simulacro) ? s.simulacro : []
const sim = lista[s.vuelta]
if (sim === undefined) throw new Error('CADENA_SIMULACRO_AGOTADO · el ensayo no trae respuesta simulada para la vuelta ' + s.vuelta)
const body = sim && sim.__fallo ? { success: false, error: String(sim.__fallo), cost_usd: 0 } : { success: true, structured_output: sim, cost_usd: 0 }
return [{ json: { ...s, agente: { statusCode: 200, body } } }]

// ② ARMAR LA LLAMADA AL AGENTE · el cuerpo COMPLETO lo armó la ruta (tarea, esquema, tope, razonamiento, modelo): aquí solo se le pone el contexto del flujo
// 🔴 `workflow_id` + `workflow_execution_id` SIEMPRE (canon: agentes solo vía workflows) · `dry_run` EXPLÍCITO y booleano · `force_restart` para que no devuelva una respuesta vieja del checkpoint
const s = $input.first().json
const llamada = { ...s.run_sdk, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id, force_restart: true, dry_run: s.seco === true }
return [{ json: { ...s, llamada } }]

// ③ ARMAR `guardar` · lo que volvió del agente (o del simulacro) tal cual, sin interpretarlo: el código de la ruta decide si sirve
const entrada = $input.first().json || {}
const simulado = !!(entrada.agente && entrada.paso)
const s = simulado ? entrada : $('② Armar la llamada').last().json
const resp = simulado ? entrada.agente : entrada
const b = resp.body && typeof resp.body === 'object' ? resp.body : {}
// un corte de la llamada (red, 290 s) llega como `{ error: { message } }` sin statusCode: se cuenta como llamada FALLIDA con sus palabras
const corte = resp.error && typeof resp.error === 'object' ? String(resp.error.message || resp.error.name || 'la llamada se cortó') : (typeof resp.error === 'string' ? resp.error : null)
const ok = Number(resp.statusCode) === 200 && b.success === true
const resultado = ok
  ? { success: true, structured_output: b.structured_output, cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null, cerrada_por_tope: b.cerrada_por_tope === true }
  : { success: false, error: String(b.error || b.detail || (corte ? 'LLAMADA_CORTADA · ' + corte : 'HTTP ' + resp.statusCode)).slice(0, 400), cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null, cerrada_por_tope: b.cerrada_por_tope === true }
const guardar = { accion: 'guardar', campana_id: s.campana_id, seco: s.seco, corrida_id: s.corrida_id, resultado, correccion: !!s.correccion, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
if (s.tanda !== null && s.tanda !== undefined) { guardar.tanda = s.tanda; guardar.modo = s.correccion && s.correccion.modo ? s.correccion.modo : 'tanda' }
return [{ json: { ...s, guardar } }]

// ④ ¿Y AHORA? · lo que dijo `guardar`: terminó bien · la campaña necesita a Emilio · UNA corrección · un reintento. Nada de reintentos sin tope: la ruta ya cuenta (máx. 3) y aquí hay un tope propio de vueltas.
const s = $('③ Armar guardar').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
const base = { ...s }
delete base.guardar; delete base.run_sdk; delete base.llamada; delete base.agente; delete base.headers
if (status >= 400) throw new Error('CADENA_GUARDAR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle'))
if (b.necesita_humano) return [{ json: { ...base, fin: true, resultado: 'necesita_humano', alerta: b.alerta || null, fichas: b.fichas || [], detalle: b } }]
if (b.ok === true || b.ya_guardada === true) return [{ json: { ...base, fin: true, resultado: 'ok', detalle: b } }]
if (s.vuelta >= 6) throw new Error('CADENA_DEMASIADAS_VUELTAS · más de 6 vueltas en un paso: algo está mal · se DETIENE')
if (b.correccion === true) return [{ json: { ...base, fin: false, vuelta: s.vuelta + 1, correccion: { fichas: b.fichas || [], fila_ids: b.fila_ids || [], modo: b.modo || 'tanda' } } }]
if (b.reintentar === true) return [{ json: { ...base, fin: false, vuelta: s.vuelta + 1, correccion: s.correccion || null } }]
throw new Error('CADENA_RESPUESTA_NO_ENTENDIDA · ' + JSON.stringify(b).slice(0, 300))

// ⑤ SALIDA · lo que el sub-flujo le devuelve a la puerta (los sub-flujos NO llaman a la sala: el cable de vuelta lo manda la puerta)
const s = $input.first().json
const d = s.detalle && typeof s.detalle === 'object' ? s.detalle : {}
return [{ json: { paso: s.paso, campana_id: s.campana_id, tanda: s.tanda ?? null, resultado: s.resultado, alerta: s.alerta || null, fichas: s.fichas || [], fechas_pedidas: d.fechas_pedidas || [], detalle: d, ...(s.jefatura ? { jefatura: s.jefatura } : {}) } }]

// JEF · armar · ESTRATEGIA / CALENDARIO · J7 · CC#1 · 2026-10-14 · en el sub-flujo, entre «④ ¿Termina?» (terminó bien o necesita humano) y «⑤ Salida».
// CONDICIÓN 4 (mecanismo de espera «antes de pasar de paso»): el sub-flujo NO termina hasta que la revisión cierre o se acabe el plazo, y la puerta de la cadena solo sigue con el paso siguiente cuando
// el sub-flujo devuelve su salida; así la estrategia no la lee el calendario ni el calendario llega a producción mientras se revisa. Solo se revisa lo que terminó BIEN (resultado ok):
// con `necesita_humano` o `ya_hecha` no se abre (regla 8: la cadena ya está detenida y la jefatura no lo pasa por encima).
// NO lanza: si algo no cuadra, `abrir = false` y todo sigue como hoy. La ENTREGA de la corrección no se aplica aquí (ver el papel: hace falta `guardar_revisada` antes de activar este tipo).
const CFG = {"max_sondeos":16,"tipo":"estrategia","plazo_s":1200,"cada_s":90,"correccion_aplicable":false,"titulo_del_pedido":"Pedido de la estrategia (trae manual, plan y reglas)"}
const s = $input.first().json || {}
const jef = { fase: 'no_abre', motivo: '', plazo_fin: Date.now() + CFG.plazo_s * 1000 }
const no = (m) => [{ json: { jef: { ...jef, motivo: m }, orig: s } }]
if (s.resultado !== 'ok') return no('el paso no terminó bien (' + String(s.resultado) + '): no hay nada nuevo que revisar')
if (typeof s.seco !== 'boolean') return no('seco no es booleano: no se abre')
// 🔴 Hasta que exista `guardar_revisada` la corrección de la jefatura NO se aplica (se pagaría y no se usaría): en REAL este tipo no abre aunque esté en `tipos_activos`; el seco sí (US$ 0: sirve para probar la espera).
if (CFG.correccion_aplicable !== true && s.seco !== true) return no('la corrección de la jefatura todavía no se puede aplicar (falta `guardar_revisada`): en real no se abre; el seco sí')
let salida = null, run = null
try { salida = $('③ Armar guardar').last().json.guardar.resultado.structured_output } catch (x) { return no('no hay salida de «③ Armar guardar»') }
try { run = $('① ¿Qué dijo?').last().json.run_sdk } catch (x) { return no('no hay pedido de «① ¿Qué dijo?»') }
if (!salida || typeof salida !== 'object') return no('el empleado no entregó un objeto')
if (!run || typeof run.client_id !== 'string' || !run.client_id) return no('el pedido no trae client_id')
if (typeof s.campana_id !== 'string' || !s.campana_id) return no('falta campana_id')
const d = s.detalle && typeof s.detalle === 'object' ? s.detalle : {}
const corrida = s.corrida_id !== undefined && s.corrida_id !== null ? 'c' + String(s.corrida_id) : null
if (!corrida) return no('falta corrida_id')
const artifact_id = CFG.tipo === 'calendario' ? s.campana_id + ':calendario:t' + String(s.tanda ?? 1) + ':' + corrida : s.campana_id + ':estrategia:' + corrida
const contexto = []
if (typeof run.task === 'string' && run.task.trim()) contexto.push({ titulo: CFG.titulo_del_pedido, texto: run.task, funcion: 'el pedido que recibió el empleado: trae el manual, el plan y lo que debía cumplir' })
const avisos = Array.isArray(d.avisos) ? d.avisos.map((a) => String(a)).slice(0, 20) : []
const sobre = {
  artifact_type: CFG.tipo,
  artifact_id,
  client_id: run.client_id,
  journey_id: null,
  payload: {
    texto: JSON.stringify(salida),
    version: CFG.tipo === 'estrategia' && Number.isInteger(d.version) && d.version >= 1 ? d.version : 1,
    dry_run: s.seco,
    devolver_a: { tipo: 'ninguno', destino: '' },
    chequeos_previos: { pasaron: true, necesita_humano: false, marcas: avisos },
    contexto,
  },
}
return [{ json: { jef: { ...jef, fase: 'abrir', motivo: '' }, abrir: true, sobre, orig: s } }]

// JEF · ¿cómo abrió? · J7 · CC#1 · 2026-10-14 · lo que contestó `POST /api/jefatura/revisiones` (abrir). NUNCA lanza: cualquier cosa rara queda como fase `error` y el productor sigue como hoy.
// Fases: cerrada (la ruta ya cerró) · esperar (hay un turno de agente por despertar) · espera_sin_turno (la revisión ya existía y sigue abierta o cerró: se lee) · no_abre (409: apagada, tipo no activo, fuera del ensayo, sin otra vuelta…) · error.
const CFG = {"max_sondeos":16,"tipo":"estrategia","plazo_s":1200,"cada_s":90,"correccion_aplicable":false,"titulo_del_pedido":"Pedido de la estrategia (trae manual, plan y reglas)"}
const s = $('JEF · armar').first().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' && !Array.isArray(r.body) ? r.body : {}
const jef = { ...s.jef }
if (status === 200 && b.accion === 'cerrado' && b.revision_id) {
  Object.assign(jef, { fase: 'cerrada', revision_id: String(b.revision_id), salida: b.salida && typeof b.salida === 'object' ? b.salida : null, resultado: b.resultado || null })
} else if (status === 200 && b.accion === 'esperar' && b.revision_id && b.turno && typeof b.turno === 'object') {
  Object.assign(jef, { fase: 'esperar', revision_id: String(b.revision_id), turno: b.turno })
} else if (status === 200 && b.accion === 'ya_existia' && b.revision_id) {
  Object.assign(jef, { fase: 'espera_sin_turno', revision_id: String(b.revision_id), estado_previo: b.estado || null })
} else if (status === 409) {
  Object.assign(jef, { fase: 'no_abre', motivo: String(b.motivo || b.error || '409') })
} else {
  const corte = r.error && typeof r.error === 'object' ? String(r.error.message || r.error.name || 'la llamada se cortó') : null
  Object.assign(jef, { fase: 'error', http: Number.isFinite(status) ? status : null, motivo: String(b.error || b.detalle || corte || ('HTTP ' + String(r.statusCode))).slice(0, 300) })
}
return [{ json: { jef } }]

// JEF · ¿cerró? · J7 · CC#1 · 2026-10-14 · lo que contestó `POST /api/jefatura/revisiones` (leer). NUNCA lanza.
// cerrada = estado terminal con su salida · seguir = todavía abierta y queda plazo · plazo = se acabó el tiempo (lo que llegue tarde NO se guarda) · error = cerró sin salida.
// Un fallo pasajero de la lectura (5xx, red) no corta la espera: se sigue sondeando hasta el plazo o el tope de sondeos.
const CFG = {"max_sondeos":16,"tipo":"estrategia","plazo_s":1200,"cada_s":90,"correccion_aplicable":false,"titulo_del_pedido":"Pedido de la estrategia (trae manual, plan y reglas)"}
const base = $('JEF · ¿cómo abrió?').first().json.jef
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' && !Array.isArray(r.body) ? r.body : {}
const TERMINALES = ['cerrada', 'cerrada_por_tope', 'fallida']
const sondeos = Number($runIndex) + 1
const jef = { ...base, sondeos }
if (status === 200 && TERMINALES.indexOf(b.estado) !== -1) {
  if (b.salida && typeof b.salida === 'object') Object.assign(jef, { fase: 'cerrada', salida: b.salida, resultado: b.resultado || null })
  else Object.assign(jef, { fase: 'error', motivo: 'la revisión cerró (' + String(b.estado) + ') pero la lectura no trajo su salida' })
} else if (Date.now() > Number(base.plazo_fin) || sondeos >= CFG.max_sondeos) {
  Object.assign(jef, { fase: 'plazo', motivo: 'se acabó la espera (' + String(CFG.plazo_s) + ' s) sin que la revisión cerrara: lo que llegue tarde no se guarda' })
} else {
  Object.assign(jef, { fase: 'seguir' })
}
return [{ json: { jef } }]

// JEF · aplicar · ESTRATEGIA / CALENDARIO · J7 · CC#1 · 2026-10-14 · sin revisión cerrada devuelve EXACTAMENTE el ítem que traía «④ ¿Termina?»: idéntico a hoy.
// Con revisión cerrada le suma `jefatura` (resultado, marcas, desacuerdos, costo): «⑤ Salida» lo pasa a la puerta. NO cambia la estrategia ni el calendario guardados (la corrección se aplica con otra pieza: `guardar_revisada`).
const CFG = {"max_sondeos":16,"tipo":"estrategia","plazo_s":1200,"cada_s":90,"correccion_aplicable":false,"titulo_del_pedido":"Pedido de la estrategia (trae manual, plan y reglas)"}
const entrada = $input.first().json || {}
const orig = $('JEF · armar').first().json.orig
const jef = entrada.jef && typeof entrada.jef === 'object' ? entrada.jef : {}
if (jef.fase !== 'cerrada' || !jef.salida || typeof jef.salida !== 'object') return [{ json: orig }]
const sal = jef.salida
const marcas = sal.marcas && typeof sal.marcas === 'object' ? sal.marcas : {}
return [{ json: { ...orig, jefatura: {
  revision_id: jef.revision_id || sal.revision_id || null,
  resultado: String(sal.resultado || jef.resultado || ''),
  con_desacuerdo: marcas.con_desacuerdo === true,
  sin_segunda_mirada: marcas.sin_segunda_mirada === true,
  desacuerdos: Array.isArray(sal.desacuerdos) ? sal.desacuerdos.map((x) => String(x).slice(0, 300)).slice(0, 8) : [],
  costo_usd: typeof sal.costo_usd === 'number' ? sal.costo_usd : null,
  simulado: sal.simulado === true,
  correccion_aplicada: false,
} } }]

// ⓪ ENTRADA DEL SUB-FLUJO · cadena · estrategia · CC#1 · 2026-10-09 · diseño v2 §3.7
// Este flujo PAGA un agente. El pedido trae `seco` EXPLÍCITO (true|false): no se asume nunca (lección 28-sep: un `dry_run` que moría en el primer nodo cobró US$ 0,37) · se DETIENE antes de gastar.
const e = $input.first().json || {}
if (typeof e.campana_id !== 'string' || e.campana_id.trim() === '') throw new Error('CADENA_SIN_CAMPANA · falta campana_id · se DETIENE y no escribe nada')
if (typeof e.seco !== 'boolean') throw new Error('CADENA_SECO_AUSENTE · el pedido debe traer seco explícito (true o false) · se DETIENE antes de gastar')
const tanda = false ? (Number.isInteger(e.tanda) && e.tanda >= 1 ? e.tanda : 1) : null
// el simulacro (respuestas enlatadas del agente, UNA por vuelta) SOLO existe en seco: en real se ignora por completo y el agente se llama de verdad
const simulacro = e.seco === true && Array.isArray(e.simulacro) ? e.simulacro : null
return [{ json: { paso: 'estrategia', campana_id: e.campana_id, seco: e.seco, tanda, simulacro, vuelta: 0, correccion: null, workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) } }]

// ① ARMAR EL PEDIDO A LA CADENA · la entrada de cada vuelta (la primera, o la que sigue a una corrección / un reintento)
const s = $input.first().json
const pedido = { accion: 'preparar', campana_id: s.campana_id, seco: s.seco, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
if (s.tanda !== null && s.tanda !== undefined) pedido.tanda = s.tanda
if (s.correccion) pedido.correccion = s.correccion
return [{ json: { ...s, pedido } }]

// ① ¿QUÉ DIJO `preparar`? · tres cosas buenas (lista para llamar · ya hecha · la campaña ya quedó en necesita_humano) y todo lo demás FALLA RUIDOSO antes de gastar
const s = $('① Armar el pedido').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
const base = { ...s }
delete base.pedido
if (status === 200 && b.ya_hecha === true) return [{ json: { ...base, fin: true, resultado: 'ya_hecha', detalle: b } }]
if (status === 200 && b.run_sdk) return [{ json: { ...base, fin: false, corrida_id: b.corrida_id, headers: b.headers || {}, run_sdk: b.run_sdk, intento: b.intento || 1 } }]
// el tope (de presupuesto o de intentos) ya dejó la campaña en necesita_humano con su reloj: no es un error del flujo, es un fin declarado
if (status === 409 && (b.error === 'presupuesto_agotado' || b.error === 'intentos_agotados')) return [{ json: { ...base, fin: true, resultado: 'necesita_humano', alerta: b.alerta || null, detalle: b } }]
throw new Error('CADENA_PREPARAR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · no se llamó a ningún agente')

// ② SIMULACRO · SOLO en seco: la respuesta enlatada del agente para esta vuelta (cero llamadas al modelo, US$ 0). En real este nodo NO existe en el camino.
// Cada elemento del simulacro es el objeto estructurado que el agente devolvería, o `{ "__fallo": "texto" }` para simular una llamada que falla.
const s = $input.first().json
const lista = Array.isArray(s.simulacro) ? s.simulacro : []
const sim = lista[s.vuelta]
if (sim === undefined) throw new Error('CADENA_SIMULACRO_AGOTADO · el ensayo no trae respuesta simulada para la vuelta ' + s.vuelta)
const body = sim && sim.__fallo ? { success: false, error: String(sim.__fallo), cost_usd: 0 } : { success: true, structured_output: sim, cost_usd: 0 }
return [{ json: { ...s, agente: { statusCode: 200, body } } }]

// ② ARMAR LA LLAMADA AL AGENTE · el cuerpo COMPLETO lo armó la ruta (tarea, esquema, tope, razonamiento, modelo): aquí solo se le pone el contexto del flujo
// 🔴 `workflow_id` + `workflow_execution_id` SIEMPRE (canon: agentes solo vía workflows) · `dry_run` EXPLÍCITO y booleano · `force_restart` para que no devuelva una respuesta vieja del checkpoint
const s = $input.first().json
const llamada = { ...s.run_sdk, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id, force_restart: true, dry_run: s.seco === true }
return [{ json: { ...s, llamada } }]

// ③ ARMAR `guardar` · lo que volvió del agente (o del simulacro) tal cual, sin interpretarlo: el código de la ruta decide si sirve
const entrada = $input.first().json || {}
const simulado = !!(entrada.agente && entrada.paso)
const s = simulado ? entrada : $('② Armar la llamada').last().json
const resp = simulado ? entrada.agente : entrada
const b = resp.body && typeof resp.body === 'object' ? resp.body : {}
// un corte de la llamada (red, 290 s) llega como `{ error: { message } }` sin statusCode: se cuenta como llamada FALLIDA con sus palabras
const corte = resp.error && typeof resp.error === 'object' ? String(resp.error.message || resp.error.name || 'la llamada se cortó') : (typeof resp.error === 'string' ? resp.error : null)
const ok = Number(resp.statusCode) === 200 && b.success === true
const resultado = ok
  ? { success: true, structured_output: b.structured_output, cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null, cerrada_por_tope: b.cerrada_por_tope === true }
  : { success: false, error: String(b.error || b.detail || (corte ? 'LLAMADA_CORTADA · ' + corte : 'HTTP ' + resp.statusCode)).slice(0, 400), cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null, cerrada_por_tope: b.cerrada_por_tope === true }
const guardar = { accion: 'guardar', campana_id: s.campana_id, seco: s.seco, corrida_id: s.corrida_id, resultado, correccion: !!s.correccion, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
if (s.tanda !== null && s.tanda !== undefined) { guardar.tanda = s.tanda; guardar.modo = s.correccion && s.correccion.modo ? s.correccion.modo : 'tanda' }
return [{ json: { ...s, guardar } }]

// ④ ¿Y AHORA? · lo que dijo `guardar`: terminó bien · la campaña necesita a Emilio · UNA corrección · un reintento. Nada de reintentos sin tope: la ruta ya cuenta (máx. 3) y aquí hay un tope propio de vueltas.
const s = $('③ Armar guardar').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
const base = { ...s }
delete base.guardar; delete base.run_sdk; delete base.llamada; delete base.agente; delete base.headers
if (status >= 400) throw new Error('CADENA_GUARDAR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle'))
if (b.necesita_humano) return [{ json: { ...base, fin: true, resultado: 'necesita_humano', alerta: b.alerta || null, fichas: b.fichas || [], detalle: b } }]
if (b.ok === true || b.ya_guardada === true) return [{ json: { ...base, fin: true, resultado: 'ok', detalle: b } }]
if (s.vuelta >= 6) throw new Error('CADENA_DEMASIADAS_VUELTAS · más de 6 vueltas en un paso: algo está mal · se DETIENE')
if (b.correccion === true) return [{ json: { ...base, fin: false, vuelta: s.vuelta + 1, correccion: { fichas: b.fichas || [], fila_ids: b.fila_ids || [], modo: b.modo || 'tanda' } } }]
if (b.reintentar === true) return [{ json: { ...base, fin: false, vuelta: s.vuelta + 1, correccion: s.correccion || null } }]
throw new Error('CADENA_RESPUESTA_NO_ENTENDIDA · ' + JSON.stringify(b).slice(0, 300))

// ⑤ SALIDA · lo que el sub-flujo le devuelve a la puerta (los sub-flujos NO llaman a la sala: el cable de vuelta lo manda la puerta)
